  var cards=[].slice.call(deck.querySelectorAll('.deck-card')), tabs=[].slice.call(deck.querySelectorAll('.deck-nav button[role="tab"]'));
  var reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches, MS=reduce?14000:8000, cur=0, timer=null, hold=false, stopped=false;
  var pb=deck.querySelector('.deck-pause');
