  var wsClip=document.getElementById('ws-clip');
  // the field clip plays only while its card is showing, and never for reduced-motion visitors
  function ws(on){ if(!wsClip) return; if(on&&!reduce){ var pr=wsClip.play(); if(pr&&pr.catch) pr.catch(function(){}); } else wsClip.pause(); }
  function show(i){cur=(i+cards.length)%cards.length;
    cards.forEach(function(c,k){c.classList.toggle('is-off',k!==cur);c.setAttribute('aria-hidden',k!==cur?'true':'false');});
    tabs.forEach(function(t,k){t.setAttribute('aria-selected',k===cur?'true':'false');});
    ws(!!cards[cur].querySelector('#ws-video')); run();}
  function run(){clearTimeout(timer);deck.classList.remove('playing'); if(hold||stopped) return;
    var ms=+(cards[cur].getAttribute('data-ms')||MS); if(reduce) ms=Math.max(ms,MS); deck.style.setProperty('--deck-ms',ms+'ms');
    void deck.offsetWidth; deck.classList.add('playing'); timer=setTimeout(function(){show(cur+1);},ms);}
